/**
 * The reference-workflow scoreboard.
 *
 * `evaluation-report.ts` beside this file is generated by `pnpm eval:fixtures`,
 * which drives the three curated workflows across the public API with the
 * deterministic contract fakes and scores them against gold fixtures that live
 * in the test suite. Only counts cross into this bundle: no article number, no
 * request wording, and no fixture answer, so the served summary cannot become a
 * back door to the answer sheet. Timings are left out too, which is what lets
 * the committed file stay byte-stable between runs.
 *
 * This module turns those counts into the sentences System details shows. It
 * describes what was measured and how, including where the fake reranker asked
 * for confirmation the fixtures did not call for — a cautious extra question is
 * a different result from a wrong acceptance, and the drawer says which it was.
 */

export type ScenarioSummary = {
  scenarioId: string
  lines: number
  extractionComplete: boolean
  customerCorrect: boolean
  shortlistHits: number
  topThreeHits: number
  selectionCorrect: number
  quantityCorrect: number
  divergedAfterAsking: number
  divergedWithoutAsking: number
  reviewLinesInGold: number
  reviewLinesObserved: number
  extraReviewLines: number
  missedReviewLines: number
  priced: boolean
  delivered: boolean
}

export type EvaluationTotals = {
  scenarios: number
  lines: number
  extractionComplete: number
  customerCorrect: number
  shortlistHits: number
  topThreeHits: number
  selectionCorrect: number
  quantityCorrect: number
  divergedAfterAsking: number
  divergedWithoutAsking: number
  reviewLinesInGold: number
  reviewLinesObserved: number
  extraReviewLines: number
  missedReviewLines: number
  priced: number
  delivered: number
}

export type ReferenceEvaluationSummary = {
  mode: "fixtures" | "live"
  providers: { ocr: string; extraction: string; rerank: string }
  scenarios: ScenarioSummary[]
  totals: EvaluationTotals
}

/**
 * Reviewer-facing names for the scenarios the generated report counts. It is a
 * lookup rather than a total record because the identifiers arrive from that
 * generated file: one this build does not recognise falls back to itself.
 */
const SCENARIO_NAMES = new Map([
  ["routine-replenishment", "Routine replenishment"],
  ["messy-forwarded-request", "Messy forwarded request"],
  ["ambiguous-replacement-parts", "Ambiguous replacement parts"],
])

/** The scoreboard as System details renders it: a state and its sentences. */
export type EvaluationSection = {
  state: "planned" | "measured"
  summary: string
  rows: string[]
}

/** How the drawer describes the measurement. Facts only, no marketing. */
export function evaluationSection(
  summary: ReferenceEvaluationSummary
): EvaluationSection {
  const { totals } = summary

  if (totals.scenarios === 0) {
    return {
      state: "planned",
      summary:
        "Three fixtures contain the reference results for the sample requests. The test suite stores these results. The browser cannot read them.",
      rows: ["This build does not have a fixture evaluation."],
    }
  }

  return {
    state: "measured",
    summary: `The test replays three sample requests through the full API. Test providers make the result repeatable. These values measure fixtures, not production use.`,
    rows: [
      `${totals.lines} lines in ${totals.scenarios} runs. Correct customers: ${totals.customerCorrect}/${totals.scenarios}. Complete extractions: ${totals.extractionComplete}/${totals.scenarios}.`,
      `Correct product in shortlist: ${totals.shortlistHits}/${totals.lines}. Correct product in top three: ${totals.topThreeHits}/${totals.lines}.`,
      selectionRow(totals),
      reviewRow(totals),
      `Priced runs: ${totals.priced}/${totals.scenarios}. Simulated deliveries: ${totals.delivered}/${totals.scenarios}.`,
      ...summary.scenarios.map(
        (scenario) =>
          `${SCENARIO_NAMES.get(scenario.scenarioId) ?? scenario.scenarioId}: ${scenario.selectionCorrect}/${scenario.lines} correct lines. Lines sent to review: ${scenario.reviewLinesObserved}.`
      ),
      "Run pnpm eval:live to test live providers. Continuous integration does not run this command.",
    ],
  }
}

/**
 * The final answer, and where it differed.
 *
 * A line that differs on a question the run had already stopped to ask is not
 * the same failure as one it settled by itself: the evaluation approves each
 * proposal unchanged so that the pipeline's own answer is what gets scored, and
 * an owner would have corrected that line in the review node. Both counts are
 * stated, because collapsing them would flatter the number.
 */
function selectionRow(totals: EvaluationTotals): string {
  const base = `Correct final products: ${totals.selectionCorrect}/${totals.lines}. Correct quantities: ${totals.quantityCorrect}/${totals.lines}.`

  const differed: string[] = []
  if (totals.divergedAfterAsking > 0) {
    differed.push(
      `${totals.divergedAfterAsking} reviewed lines had a different product`
    )
  }

  if (totals.divergedWithoutAsking > 0) {
    differed.push(
      `${totals.divergedWithoutAsking} automatically accepted lines had a different product`
    )
  }

  return differed.length > 0
    ? `${base} Differences: ${differed.join("; ")}.`
    : base
}

function reviewRow(totals: EvaluationTotals): string {
  const base = `Lines sent to review: ${totals.reviewLinesObserved}. Reference review lines: ${totals.reviewLinesInGold}.`

  if (totals.missedReviewLines > 0) {
    return `${base} The system accepted ${totals.missedReviewLines} uncertain lines without review.`
  }

  if (totals.extraReviewLines > 0) {
    return `${base} The system sent ${totals.extraReviewLines} additional lines to review.`
  }

  return `${base} The system did not accept an uncertain line without review.`
}
